// Looks up images generated by `npm run images` (see src/data/imageManifest.json).
import manifest from '../data/imageManifest.json';

type Entry = { widths: number[]; width: number; height: number; avif?: boolean };
const images = manifest as Record<string, Entry>;

/** If `src` is a generated image (e.g. "/images/board/name"), returns its manifest entry. */
export function imageEntry(src?: string): (Entry & { base: string }) | null {
  if (!src) return null;
  const base = src.replace(/-\d+\.(webp|avif)$/, '');
  const entry = images[base];
  return entry ? { ...entry, base } : null;
}

/** A plain URL for an image — the smallest generated width that is at least `minWidth`. */
export function imageUrl(src?: string, minWidth = 0): string {
  const entry = imageEntry(src);
  if (!entry) return src || '';
  const w = entry.widths.find((x) => x >= minWidth) ?? entry.widths[entry.widths.length - 1];
  return `${entry.base}-${w}.webp`;
}
